#include <stdio.h> int main() { // 定义指针类型变量和取变量地址 int v1=666; int *v2=&v1; // 定义了指针类型变量v2，指向了v1的地址，v2中存着v1的地址 // v1和v2 不是一个东西，都不是一个类型，更不相等 printf("v2的值是:%p
",v2); // 0061FF18 // v2 指向的地址里面到底存了什么--》我们存了66 printf("v2解引用后是：%d
",*v2); // 修改变量的值 v1=999; // 问：v2的值会变吗？--没变 printf("v2的值是:%p
",v2); // 问：v2指向的值，现在是多少？ 999 printf("v2解引用后是：%d
",*v2); return 0; }

#include <stdio.h> int main() { // 指针的零值和长度 如果不赋值，随便指向了一个地址，有时候就是 00000000 ,咱们统一让他指向 NULL int *v2=NULL; int *v3=NULL; int *v4=NULL; printf("%p
",v2); printf("%p
",v3); printf("%p
",v4); int i=99; v2=&i; printf("%p
",v2); printf("指针大小：%d
",sizeof(v2)); // 4 if(!v3){ // 通过 ！指针，直接判断是否为空 printf("是空"); } return 0; }

#include <stdio.h> void changeA(int a){ a=999; printf("内部是：%d
",a); } void changePointA(int *a){ *a=999; printf("内部是：%d
",*a); } int main() { // 指针类型参数 // 1 参数传递，修改值 int a=1; // 调用changeA，修改a的值，a不会被真正的修改掉 changeA(a); // 把a复制了一份传进去了，里面改了，不会影响原来的值 printf("外部是：%d
",a); // 2 参数传递，指针类型修改值 int a1=1; // 调用changePointA，修改a的值，a会被真正的修改掉 changePointA(&a1); // 把a1复制了一份,由于是个地址传进去了，在函数里面改了，改的是指向的位置，会影响原来的值 printf("外部是：%d
",a1); return 0; }

#include <stdio.h> int main() { // 指针的指针 int a =100; int *p1 = &a; int **p2=&p1; // p2是指针p1的内存地址 printf("p2的值是：%p
",p2); printf("p1的值是：%p
",p1); printf("p2解引用的值是：%p--》就是p1
",*p2); printf("p2解引用再解引用：%d--》就是a
",**p2); return 0; }

#include <stdio.h> // 1 定义一个 人 结构体 struct Person{ char name[30]; int age; }; int main() { //2 结构体定义和使用 struct Person p1={"jsutin",88}; printf("人名是:%s,年龄是：%d
",p1.name,p1.age); struct Person p2={"彭于晏",34}; printf("人名是:%s,年龄是：%d
",p2.name,p2.age); // 3 结构体指针 struct Person *p3=&p2; // 打印p3指向的地址人的名字 printf("人名是：%s
",(*p3).name); // 咱们理解的方式 printf("人名是：%s
",p3->name); //推荐使用这种 return 0; }

#include <stdio.h> // 定义一个Node结构体：要存数据，存下一个的地址 struct Node { int data; struct Node *next; }; int main() { struct Node v3 = {33}; struct Node v2 = {22, &v3}; struct Node v1 = {11, &v2}; printf("v1的数据为：%d
", v1.data); // 11 printf("v1的下一个元素数据为：%d
", v1.next->data); // 22 printf("v1的下一个元素的下一个数据为：%d
", v1.next->next->data); // 33 return 0; }
